import {World,isAir} from './world.js';
import {placementRecord} from './objects.js';
export function captureRegion(world,min,max,name='Construção selecionada'){
 if(![...min,...max].every(Number.isInteger)||min.some((v,i)=>v<0||v>max[i])||!world.inside(...max))throw Error('Seleção fora dos limites ou invertida.');const [w,h,d]=max.map((v,i)=>v-min[i]+1);if(w*h*d>500000)throw Error('Seleção excede 500.000 posições.');const asset=new World(w,h,d),delta=[];
 for(let y=0;y<h;y++)for(let z=0;z<d;z++)for(let x=0;x<w;x++){const s=world.palette[world.get(x+min[0],y+min[1],z+min[2])];asset.set(x,y,z,s);if(!isAir(s))delta.push({idx:world.index(x+min[0],y+min[1],z+min[2]),before:'minecraft:air',after:s});}
 if(!delta.length)throw Error('A seleção contém apenas ar.');const indices=new Set(delta.map(c=>c.idx));if(world.placements.some(p=>p.solidIndices.some(i=>indices.has(i))))throw Error('A seleção sobrepõe um objeto registrado. Desagrupe esse objeto primeiro.');const transform={x:min[0],y:min[1],z:min[2],rotation:0,mirrorX:false,mirrorZ:false,terrain:'natural',air:'ignore',blendRadius:8,blendIterations:2,protectStructures:true};return {asset,record:placementRecord(world,asset,transform,{delta,bounds:[...min,w,h,d]},{name})};
}
export function createRegionUI({modal,toast,getWorld,commit,onAsset}){const button=document.createElement('button');button.id='select-region';button.className='button secondary full';button.style.marginTop='9px';button.textContent='▣ Selecionar área / agrupar construção';document.querySelector('#import-schem').after(button);button.onclick=()=>{const w=getWorld();if(!w)return toast('Gere ou abra um mapa primeiro.');const body=document.createElement('div');body.innerHTML='<p>Escolha os cantos inclusivos em coordenadas locais. A seleção explícita também reconhece construções de pedra natural. Registrar permite mover o original sem deixá-lo no lugar; copiar cria um item na biblioteca.</p><label>Nome<input id="region-name" maxlength="80" value="Minha construção"></label><div class="three-cols">'+['x','y','z'].map((k,i)=>`<label>Mínimo ${k.toUpperCase()}<input id="region-min-${k}" type="number" value="0" min="0" max="${[w.w,w.h,w.d][i]-1}"></label>`).join('')+'</div><div class="three-cols">'+['x','y','z'].map((k,i)=>`<label>Máximo ${k.toUpperCase()}<input id="region-max-${k}" type="number" value="${Math.min(15,[w.w,w.h,w.d][i]-1)}" min="0" max="${[w.w,w.h,w.d][i]-1}"></label>`).join('')+'</div><div class="heading-actions"><button id="region-copy" class="button secondary">Copiar para biblioteca</button><button id="region-register" class="button primary">Registrar original para mover</button></div><hr><p>Desagrupar mantém os blocos e remove o vínculo de objeto, permitindo selecionar outra área.</p><div id="region-groups"></div>';modal('Seleção manual de construções',body);const q=s=>body.querySelector(s);for(const record of w.placements){const b=document.createElement('button');b.className='button secondary full';b.textContent='Desagrupar · '+record.name;b.onclick=async()=>{try{await commit({baseRevision:w.revision,delta:[],placementsBefore:structuredClone(w.placements),placementsAfter:w.placements.filter(p=>p.id!==record.id)},'Desagrupar construção');document.querySelector('#dialog').close();}catch(e){toast(e.message);}};q('#region-groups').append(b);}
  const act=register=>async()=>{try{if(getWorld()!==w)throw Error('Mapa mudou. Abra a seleção novamente.');const min=['x','y','z'].map(k=>Number(q('#region-min-'+k).value)),max=['x','y','z'].map(k=>Number(q('#region-max-'+k).value)),name=q('#region-name').value,{asset,record}=captureRegion(w,min,max,name);if(register)await commit({baseRevision:w.revision,delta:[],placementsBefore:structuredClone(w.placements),placementsAfter:[...structuredClone(w.placements),record]},'Registrar construção');else await onAsset(asset,name);document.querySelector('#dialog').close();toast(register?'Construção registrada. Clique nela no 3D para mover.':'Seleção copiada para a biblioteca.');}catch(e){toast(e.message);}};q('#region-copy').onclick=act(false);q('#region-register').onclick=act(true);
 };}
